type operationLocation struct {
	operation, path string
	source          *runtime.Source
	kind            runtime.ErrorKind
}

//go:noinline
func (c *operationLocation) failure(err error, path string, offset, width int) error {
	if path == "" {
		path = c.path
	}
	return locateOperationKind(err, c.operation, path, offset, width, *c.source, c.kind)
}

//go:noinline
func (c *operationLocation) nilWriter() error {
	return &runtime.OperationError{Operation: c.operation, Kind: runtime.InvalidValue, Location: runtime.Location{Path: c.path, BitOffset: -1, Source: *c.source}, Detail: "nil writer"}
}

func locateIndex(err error, path string, index int) error {
	if err == nil {
		return nil
	}
	if deferred, ok := runtime.DeferIndex(err, path, index, locateIndex); ok {
		return deferred
	}
	var previous *runtime.OperationError
	if errors.As(err, &previous) {
		copy := *previous
		copy.Location.Path = indexedPath(copy.Location.Path, path, index)
		return &copy
	}
	var cause *runtime.DecodeError
	if errors.As(err, &cause) {
		return &runtime.OperationError{Operation: "decode", Kind: cause.Kind, Location: runtime.Location{Path: indexedPath(cause.Path, path, index), BitOffset: cause.Offset}, Cause: err}
	}
	return err
}

// indexedPath inserts the list immediately after its enclosing codec level.
// A list already present in the path receives the index on that component.
func indexedPath(full, path string, index int) string {
	parent := indexParent(path)
	start := 0
	for rest := full; rest != ""; {
		component, tail, more := strings.Cut(rest, "/")
		end := start + len(component)
		if component == parent {
			if parent == path {
				return full[:end] + "[" + strconv.Itoa(index) + "]" + full[end:]
			}
			next, _, _ := strings.Cut(tail, "/")
			if next == path {
				return full[:end] + "/" + path + "[" + strconv.Itoa(index) + "]" + strings.TrimPrefix(tail, path)
			}
			return full[:end] + "/" + path + "[" + strconv.Itoa(index) + "]" + full[end:]
		}
		if !more {
			break
		}
		start = end + 1
		rest = tail
	}
	if full == "" {
		return path + "[" + strconv.Itoa(index) + "]"
	}
	return path + "[" + strconv.Itoa(index) + "]/" + full
}

func errorPath(parent, child string) string {
	if child == "" || parent == child || strings.HasSuffix(parent, "/"+child) {
		return parent
	}
	if parent == "" {
		return child
	}
	return parent + "/" + child
}

func constraintFailure(r *runtime.Reader, start, width int, detail string) error {
	return r.ErrorAt(runtime.InvalidValue, start, detail)
}

